// === Tab: Particle ===
class Particle {
	constructor(xStartingPosition, yStartingPosition, noiseIncreaseAmount, rotationSpeed, movementSpeed , psize) {
		this.rOff = random(100);
		this.r = random(TWO_PI);
		this.x = xStartingPosition;
		this.y = yStartingPosition;
		this.movementSpeed = movementSpeed;
		this.increaseAmount = noiseIncreaseAmount;
		this.xv = 0;
		this.yv = 0;
		this.rotationSpeed = rotationSpeed;
    this.size = psize;
	}

	draw() {
		strokeWeight(0.4);//outline size

		stroke(0);//outline color

		ellipse( this.x-this.xv, this.y-this.yv , this.size,this.size);

	}

	update() {


		this.rOff += this.increaseAmount;
		this.r += map(noise(this.rOff), 0, 1, -this.rotationSpeed, this.rotationSpeed);

		this.xv += cos(this.r) * this.movementSpeed*this.r/10;
		this.yv += sin(this.r) * this.movementSpeed*this.r/10;

		this.x += this.xv;
		this.y += this.yv;
	}
}

